import pathlib, sys
needles = ['pm-product-' + 'expert', 'pm-product-owner-' + 'review', 'product_solution_' + 'doc', 'product_thinking_' + 'ledger']
skip_dirs = {'.git', 'node_modules', '.venv', '__pycache__', 'plugins'}
root = pathlib.Path('.')
for path in root.rglob('*'):
    if not path.is_file():
        continue
    if any(part in skip_dirs for part in path.parts):
        continue
    try:
        text = path.read_text(encoding='utf-8', errors='ignore')
    except Exception:
        continue
    for needle in needles:
        if needle in text:
            print(f'{path}: contains forbidden token {needle}')
            sys.exit(1)
